/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		propName: 'globalCreateSelectedItems',
		value: []
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const id = event.payload.item.id;
	let target = null;
	switch (id) {
		case 'experience':
			target = !api.data.uib_homepage_ctrl.textToExperienceActive ? 'showExperienceCreateModal' : undefined;
			break;
		case 'experienceWithGenAI':
			target = 't2eModalOpened';
			break;
	}


	if (!target) return;

	return {
		propName: target,
		value: true
	};
}

